const board = document.getElementById('game-board');
const cells = document.querySelectorAll('.cell');
const turnIndicator = document.getElementById('turn-indicator');
const statusText = document.getElementById('game-status');
const restartBtn = document.getElementById('restart-btn');
const xWinsEl = document.getElementById('x-wins');
const oWinsEl = document.getElementById('o-wins');
const tiesCountEl = document.getElementById('ties-count');

const STORAGE_KEY = 'tictactoe_stats_v1';

let currentPlayer = 'X';
let boardState = ['', '', '', '', '', '', '', '', ''];
let isGameActive = true;
let stats = { x: 0, o: 0, ties: 0 };

const winningConditions = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8], // rows
  [0, 3, 6], [1, 4, 7], [2, 5, 8], // columns
  [0, 4, 8], [2, 4, 6]             // diagonals
];

function loadStats() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      stats = JSON.parse(saved);
      xWinsEl.textContent = stats.x;
      oWinsEl.textContent = stats.o;
      tiesCountEl.textContent = stats.ties;
    }
  } catch (e) {
    console.warn('Failed to load stats:', e);
  }
}

function saveStats() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stats));
  } catch (e) {
    console.warn('Failed to save stats:', e);
  }
}

function handleCellClick(e) {
  const cell = e.target;
  const index = parseInt(cell.dataset.index);

  if (boardState[index] !== '' || !isGameActive) return;

  boardState[index] = currentPlayer;
  cell.textContent = currentPlayer;
  cell.classList.add(currentPlayer.toLowerCase());

  checkWinner();
}

function checkWinner() {
  let roundWon = false;
  let winningLine = [];

  for (let i = 0; i < winningConditions.length; i++) {
    const [a, b, c] = winningConditions[i];
    if (boardState[a] && boardState[a] === boardState[b] && boardState[a] === boardState[c]) {
      roundWon = true;
      winningLine = [a, b, c];
      break;
    }
  }

  if (roundWon) {
    statusText.textContent = `Player ${currentPlayer} Wins!`;
    winningLine.forEach(idx => cells[idx].classList.add('win'));
    isGameActive = false;
    if (currentPlayer === 'X') stats.x++;
    else stats.o++;
    updateStatsDisplay();
    saveStats();
    return;
  }

  if (!boardState.includes('')) {
    statusText.textContent = 'Game Ended in a Draw!';
    isGameActive = false;
    stats.ties++;
    updateStatsDisplay();
    saveStats();
    return;
  }

  currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
  turnIndicator.textContent = `Player ${currentPlayer}'s Turn`;
  turnIndicator.style.color = currentPlayer === 'X' ? 'var(--color-x)' : 'var(--color-o)';
}

function updateStatsDisplay() {
  xWinsEl.textContent = stats.x;
  oWinsEl.textContent = stats.o;
  tiesCountEl.textContent = stats.ties;
}

function restartGame() {
  currentPlayer = 'X';
  boardState = ['', '', '', '', '', '', '', '', ''];
  isGameActive = true;
  statusText.textContent = '';
  turnIndicator.textContent = "Player X's Turn";
  turnIndicator.style.color = 'var(--color-x)';

  cells.forEach(cell => {
    cell.textContent = '';
    cell.className = 'cell';
  });
}

cells.forEach(cell => cell.addEventListener('click', handleCellClick));
restartBtn.addEventListener('click', restartGame);
loadStats();

:root {
  --bg: #090d16;
  --card: #131b2e;
  --border: #233150;
  --text: #f1f5f9;
  --text-muted: #94a3b8;
  --color-x: #00f0ff;
  --color-o: #f43f5e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.game-wrapper {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 1.25rem;
  width: 100%;
  max-width: 440px;
  padding: 2rem;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5);
  text-align: center;
}

.game-header {
  margin-bottom: 1.5rem;
}

.app-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: 0.5rem;
}

.turn-indicator {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-x);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin: 0 auto 1.25rem auto;
  max-width: 320px;
}

.cell {
  background: #090d16;
  border: 2px solid var(--border);
  border-radius: 0.75rem;
  aspect-ratio: 1;
  font-size: 2.25rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text);
  transition: all 0.15s ease;
}

.cell:hover:not(:disabled) {
  border-color: var(--color-x);
  background: #111a30;
}

.cell.x {
  color: var(--color-x);
}

.cell.o {
  color: var(--color-o);
}

.cell.win {
  background: #1e293b;
  border-color: #22c55e;
}

.game-status {
  font-size: 1rem;
  font-weight: 700;
  min-height: 1.5rem;
  margin-bottom: 1rem;
}

.game-footer {
  border-top: 1px solid var(--border);
  padding-top: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.restart-button {
  background: #090d16;
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.625rem 1.25rem;
  border-radius: 0.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  align-self: center;
}

.restart-button:hover {
  border-color: var(--color-x);
  color: var(--color-x);
}

.stats-row {
  display: flex;
  justify-content: space-around;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.stats-row strong {
  color: var(--text);
}
